const URL_JOGADORES = "https://api.cobra.dev/torneio/jogadores";
const URL_PARTIDAS = "https://api.cobra.dev/torneio/partidas";

async function buscarDados(url) {
  const resposta = await fetch(url);
  if (!resposta.ok) {
    throw new Error(`Erro ${resposta.status} em ${url}`);
  }
  return await resposta.json();
}

function montarRanking(jogadores, partidas) {
  const ranking = jogadores.map((jogador) => {
    const pontos = partidas
      .filter((partida) => partida.jogador === jogador.id)
      .reduce((soma, partida) => soma + partida.pontos, 0);
    return { nome: jogador.nome, pontos };
  });
  return ranking.sort((a, b) => b.pontos - a.pontos || a.nome.localeCompare(b.nome));
}

async function carregarRanking() {
  const [jogadores, partidas] = await Promise.all([buscarDados(URL_JOGADORES), buscarDados(URL_PARTIDAS)]);
  return montarRanking(jogadores, partidas);
}

console.log("=== Torneio Relâmpago ===");
try {
  const ranking = await carregarRanking();
  ranking.slice(0, 3).forEach((jogador, i) => {
    console.log(`${i + 1}. ${jogador.nome} - ${jogador.pontos} pontos`);
  });
} catch (erro) {
  console.log("Placar indisponível: " + erro.message);
}
